import json,itertools
from pathlib import Path
import numpy as np
R=Path('/workspace/research');ref=json.loads(Path('/workspace/whitebox.json').read_text());models=ref['models'];tasks=json.loads((R/'versions/pilot_v1/tasks.json').read_text());families=['arxiv_math','hle_choice','gdp_data'];data={}
for model in models:
 p=R/'results/pilot_v1'/model/'status.json'
 if not p.exists():continue
 s=json.loads(p.read_text())
 if s['status']"'!='"'ok':continue
 rows={r['id']:r for r in s['result']['items']}
 if any(r['execution_status']"'!='"'completed' for r in rows.values()):continue
 data[model]=rows
out={'status':'pending_four_model_coverage','models':list(data),'scope':'Local exploratory reuse of actual numeric-work item grades from pilot_v1. Not official reweighted feedback, not final-suite measurement, no target predictions.','prospective_rule':'Consider shared quantitative work only for a >=0.03 reasoning target-mean Pearson gain, with >=80% paired item-bootstrap improvements. Any final change must remain a positive weighted mean and explicitly count shared questions once.'}
if set(data)==set(models):
 ids={f:[t['id'] for t in tasks if t['family']==f] for f in families}
 vals={f:np.array([[data[m][id]['score'] for id in ids[f]] for m in models]) for f in families}
 mat=np.array([vals[f].mean(axis=1) for f in families]);mi={m:i for i,m in enumerate(models)}
 def corr(x,y):
  x=np.array(x);y=np.array(y);x=x-x.mean();y=y-y.mean();d=np.linalg.norm(x)*np.linalg.norm(y)
  return float(x@y/d) if d>1e-14 else 0.0
 def objective(s):return np.mean([corr([s[mi[m]] for m in target['scores']],list(target['scores'].values())) for n,target in ref['targets'].items() if n in ref['domains']['reasoning']])
 baseline=objective(mat[:2].mean(axis=0));candidates=[]
 for w in itertools.product([1,2,4],repeat=3):candidates.append((objective(np.array(w)@mat/sum(w)),w))
 best=max(candidates);default=np.array([2,2,1]);near=[z for z in candidates if z[0]>=best[0]-0.01]
 selected=min(near,key=lambda z:(np.var(np.log(np.array(z[1])/default)),sum(z[1]),z[1]));utility,w=selected
