  bm=np.array([vals[f][:,rng.integers(0,len(ids[f]),len(ids[f]))].mean(axis=1) for f in families])
  deltas.append(objective(np.array(w)@bm/sum(w))-objective(bm[:2].mean(axis=0)))
 out.update(status='analyzed',family_means={f:dict(zip(models,mat[i].tolist())) for i,f in enumerate(families)},baseline_pearson=float(baseline),best_shared_pearson=float(best[0]),selected_family_mass=dict(zip(families,w)),selected_shared_pearson=float(utility),gain=float(utility-baseline),bootstrap_improvement_fraction=float(np.mean(np.array(deltas)>0)),bootstrap_gain_percentiles_5_50_95=np.percentile(deltas,[5,50,95]).tolist())
 out['meets_prospective_rule']=out['gain']>=0.03 and out['bootstrap_improvement_fraction']>=0.8
